void rotate_matrix(int matrix[][8],int n){int layer;int first;int last;int offset;int top;for(layer=0;layer<n/2;layer=layer+1){first=layer;last=n-1-layer;for(offset=0;offset<last-first;offset=offset+1){top=matrix[first][first+offset];matrix[first][first+offset]=matrix[last-offset][first];matrix[last-offset][first]=matrix[last][last-offset];matrix[last][last-offset]=matrix[first+offset][last];matrix[first+offset][last]=top;}}}
int main(void){int a[8][8];int i;int j;int v;v=1;for(i=0;i<3;i=i+1)for(j=0;j<3;j=j+1){a[i][j]=v;v=v+1;}rotate_matrix(a,3);if(a[0][0]!=7||a[0][1]!=4||a[0][2]!=1)return 1;if(a[2][0]!=9||a[2][2]!=3)return 2;return 42;}
